-- State transitions for stream: home-assistant-state
-- Generated by ndp-gold-ddl
-- Mode: SYNC (create if not exists)

CREATE SCHEMA IF NOT EXISTS gold;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_matviews
        WHERE schemaname = 'gold'
          AND matviewname = 'home_assistant_state_transitions'
    ) THEN
        -- Create the materialized view
        CREATE MATERIALIZED VIEW gold.home_assistant_state_transitions AS
        SELECT
            event_time AS transition_time,
            ndp_id AS entity_id,
            'home-assistant-state' AS stream_id,
            -- State transition details,
            LAG(state) OVER w AS from_state,
            state AS to_state,
            -- Is this an actual state change?,
            CASE
                WHEN LAG(state) OVER w IS DISTINCT FROM state THEN TRUE
                WHEN LAG(state) OVER w IS NULL THEN TRUE
                ELSE FALSE
            END AS is_actual_transition,
            -- Duration in previous state,
            event_time - LAG(event_time) OVER w AS duration_in_previous_state,
            EXTRACT(EPOCH FROM (event_time - LAG(event_time) OVER w)) * 1000 AS duration_ms,
            -- Transition direction (for binary on/off states),
            CASE
                WHEN LAG(state) OVER w = 'off' AND state = 'on' THEN 'opening'
                WHEN LAG(state) OVER w = 'on' AND state = 'off' THEN 'closing'
                WHEN LAG(state) OVER w IS NULL THEN 'initial'
                ELSE 'unknown'
            END AS transition_direction,
            -- Device type derived from entity_id,
            CASE
                WHEN ndp_id LIKE 'door_%' THEN 'door'
                WHEN ndp_id LIKE 'window_%' THEN 'window'
                WHEN ndp_id LIKE 'motion_%' THEN 'motion'
                WHEN ndp_id LIKE 'light_%' THEN 'light'
                ELSE 'other'
            END AS device_type
        FROM silver.state_events
        WINDOW w AS (PARTITION BY ndp_id ORDER BY event_time);
        
        -- Index for efficient queries
        CREATE INDEX IF NOT EXISTS idx_home_assistant_state_time
            ON gold.home_assistant_state_transitions (transition_time DESC);
        
        CREATE INDEX IF NOT EXISTS idx_home_assistant_state_entity
            ON gold.home_assistant_state_transitions (entity_id, transition_time DESC);
        
        -- Filtered view for only actual transitions
        CREATE VIEW gold.home_assistant_state_transitions_actual AS
        SELECT * FROM gold.home_assistant_state_transitions
        WHERE is_actual_transition = TRUE;
        
        COMMENT ON MATERIALIZED VIEW gold.home_assistant_state_transitions IS
            'State transitions extracted from home-assistant-state stream. Refresh with Gold layer.';

        RAISE NOTICE 'Created transition view: gold.home_assistant_state_transitions';
    ELSE
        RAISE NOTICE 'gold.home_assistant_state_transitions already exists, skipping';
    END IF;
END $$;
